261	import java.time.Duration;
262	
263	public class TransLogClient {
264	    private static final Logger logger = LoggerFactory.getLogger(TransLogClient.class);
265	    private static final ObjectMapper mapper = new ObjectMapper();
266	    private static final HttpClient httpClient = HttpClient.newHttpClient();
267	
268	    public record ShippingQuote(BigDecimal price, int deliveryDays) {}
269	
270	    public static ShippingQuote quote(String zipCode, double weightKg, String service) throws CarrierUnavailableException {
271	        String translogUrl = System.getenv("TRANSLOG_URL");
272	        if (translogUrl == null) {
273	            throw new CarrierUnavailableException();
274	        }
275	
276	        int weightGrams = (int) Math.round(weightKg * 1000);
277	        String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s", translogUrl, zipCode, weightGrams, service);
278	
279	        try {
280	            var request = HttpRequest.newBuilder()
281	                .uri(URI.create(url))
282	                .timeout(Duration.ofSeconds(2))
283	                .GET()
284	                .build();
285	
286	            var response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
287	
288	            if (response.statusCode() != 200) {
289	                logger.warn("TransLog returned status {}", response.statusCode());
290	                throw new CarrierUnavailableException();
291	            }
292	
293	            JsonNode node = mapper.readTree(response.body());
294	
295	            if (node.has("error")) {
296	                return null;
297	            }
298	
299	            if (!node.has("price_cents") || !node.has("eta_hours")) {
300	                throw new CarrierUnavailableException();
301	            }
302	
303	            long priceCents = node.get("price_cents").asLong();
304	            BigDecimal priceReais = Money.divide(new BigDecimal(priceCents), new BigDecimal("100"));
305	
306	            int hoursEta = node.get("eta_hours").asInt();
307	            int deliveryDays = (int) Math.ceil((double) hoursEta / 24);
308	
309	            return new ShippingQuote(priceReais, deliveryDays);
310	        } catch (IOException | InterruptedException e) {
311	            logger.error("Failed to contact TransLog", e);
312	            throw new CarrierUnavailableException();
313	        }
314	    }
315	
316	    public static class CarrierUnavailableException extends Exception {
317	        public CarrierUnavailableException() {
318	            super("Carrier unavailable");
319	        }
320	    }
321	}

